// Sécurité et santé : 10 articles, 4 langues, dates échelonnées (voir DATES dans articles.mjs).
// Tout vient de pages officielles lues le 15 novembre 2026 : maximes de la Société Suisse de Sauvetage (SSS), fiche de l'Office fédéral de la santé publique
// publiée par l'État de Vaud, pages de l'État de Genève et communiqués de l'État de Vaud. Ce que ces pages ne disent pas n'est pas écrit : pas de conseil
// médical, pas de chiffre venu d'ailleurs. Pas d'article sur les orages ni sur les courants du lac : aucune source officielle suisse lue (voir TODO.md).
const SSS = (p, t) => [`Société Suisse de Sauvetage SSS, « ${t} »`, `https://www.slrg.ch/fr/prevention/${p}`];
const BAIGNADE = SSS('les-maximes-de-comportement-de-la-sss/maximes-de-la-baignade', 'Maximes de la baignade');
const RIVIERES = SSS('les-maximes-de-comportement-de-la-sss/maximes-de-comportement-en-rivieres', 'Maximes de comportement en rivières');
const FAMILLES = SSS('recommandations/recommandations-pour-les-familles', 'Recommandations pour les familles');
const HELSANA = ['Helsana, « Winterschwimmen – das bringt’s und so geht’s »', 'https://www.helsana.ch/content/helsana/de/blog/koerper/bewegung/winterschwimmen.html'];
const OFSP = ['Office fédéral de la santé publique, « Dermatite du baigneur » (fiche d’information, 2006), publiée par l’État de Vaud', 'https://www.vd.ch/fileadmin/user_upload/organisation/dse/scav/sire/Fiche_d_information_Dermatite_du_baigneur.pdf'];
const GE_PUCES = ['État de Genève, « Les puces de canard »', 'https://www.ge.ch/plages-lieux-baignade-eaux-vives-geneve/puces-canard'];
const VD_CYANO = ['État de Vaud, « Le canton recommande la prudence… face aux proliférations de cyanobactéries »', 'https://www.vd.ch/actualites/communiques-de-presse-de-letat-de-vaud/detail/communique/le-canton-recommande-la-prudence-et-soutient-les-communes-face-aux-proliferations-de-cyanobacteries'];
const VD_FEUX = ['État de Vaud, « Des feux à éclipses modernisés pour renforcer la sécurité sur les lacs romands »', 'https://www.vd.ch/actualites/communiques-de-presse-de-letat-de-vaud/detail/communique/des-feux-a-eclipses-modernises-pour-renforcer-la-securite-sur-les-lacs-romands'];
const FIN = {
  fr: '<p>Rien ici ne remplace un cours de secourisme ni l’avis d’un médecin. L’eau et le vent du moment, plage par plage, sont dans l’<a href="{app}">app Mon Lac</a>.</p>',
  en: '<p>Nothing here replaces a first-aid course or a doctor’s advice. The current water and wind, beach by beach, are in the <a href="{app}">My Lake app</a>.</p>',
  de: '<p>Nichts hier ersetzt einen Erste-Hilfe-Kurs oder den Rat einer Ärztin oder eines Arztes. Wasser und Wind von heute, Badeplatz für Badeplatz, stehen in der <a href="{app}">App Mein See</a>.</p>',
  it: '<p>Nulla qui sostituisce un corso di primo soccorso o il parere di un medico. Acqua e vento del momento, spiaggia per spiaggia, sono nell’<a href="{app}">app Il mio lago</a>.</p>' };
const P = (...t) => t.map((x) => `<p>${x}</p>`).join('\n'), UL = (...t) => `<ul class="liste">\n${t.map((x) => `  <li>${x}</li>`).join('\n')}\n</ul>`;
const LEGENDE = { fr: 'Illustration générée par IA', en: 'AI-generated illustration', de: 'KI-generierte Illustration', it: 'Illustrazione generata dall’IA' };
// slug, nom de l'image attendue, textes alternatifs [fr, en, de, it], sources, puis les quatre langues { titre, h1, desc, bref, s: [[titre de section, html], …] }.
const A = (slug, img, altIA, sources, t) => {
  const a = { slug, sante: true, img, altIA, sources };
  for (const L of ['fr', 'en', 'de', 'it']) { const { s, ...x } = t[L]; a[L] = { ...x, html: () => `${s.map(([h, p]) => `<h2>${h}</h2>\n${p}`).join('\n')}\n${FIN[L]}` }; }
  return a;
};

export const articlesSecurite = () => [
  A('maximes-baignade-sss', 'securite-maximes', ['Un ponton de bois, une bouée de sauvetage rouge accrochée au poteau, le lac calme', 'A wooden jetty, a red lifebuoy hung on the post, the calm lake', 'Ein Holzsteg, ein roter Rettungsring am Pfosten, der ruhige See', 'Un molo di legno, un salvagente rosso appeso al palo, il lago calmo'], [BAIGNADE, FAMILLES], {
    fr: { titre: 'Les six maximes de la baignade de la Société Suisse de Sauvetage', h1: 'Les six maximes de la baignade, expliquées', desc: 'Enfants accompagnés, pas d’alcool ni d’estomac chargé, pas de saut après le soleil, pas de plongeon dans l’inconnu, pas de matelas en eau profonde, pas seul au loin : les six maximes de la SSS.',
      bref: 'La <strong>Société Suisse de Sauvetage (SSS)</strong> résume la baignade en <strong>six maximes</strong> : 1) accompagner les enfants au bord de l’eau ; 2) pas d’alcool, ni estomac chargé, ni à jeun ; 3) pas de saut après un bain de soleil prolongé ; 4) pas de plongeon ni de saut dans une eau trouble ou inconnue ; 5) pas de matelas pneumatique en eau profonde ; 6) ne jamais nager seul sur de longues distances.',
      s: [['Les six maximes', UL('<strong>1.</strong> Les enfants au bord de l’eau doivent toujours être accompagnés ; les petits enfants se gardent à portée de main.', '<strong>2.</strong> Ne jamais se baigner après avoir consommé de l’alcool ou des drogues, ni l’estomac chargé, ni à jeun.', '<strong>3.</strong> Ne jamais sauter dans l’eau après un bain de soleil prolongé : le corps a besoin d’un temps d’adaptation.', '<strong>4.</strong> Ne pas plonger ni sauter dans des eaux troubles ou inconnues.', '<strong>5.</strong> Les matelas pneumatiques et tout matériel auxiliaire de natation ne doivent pas être utilisés en eau profonde.', '<strong>6.</strong> Ne jamais nager seul sur de longues distances.')],
        ['Pourquoi ces six-là ?', P('La SSS explique chaque maxime sur sa page : les petits enfants peuvent se noyer en moins de 20 secondes, sans bruit, même dans une faible profondeur ; l’alcool altère la conscience et fait surestimer ses capacités ; le choc thermique après le soleil peut causer crampes, malaise, voire un évanouissement ; des dangers invisibles se cachent dans l’eau inconnue ; un matelas peut perdre son air ; même le corps le mieux entraîné peut avoir une défaillance.', 'Nous détaillons chacune dans un article : <a href="{blog:enfants-au-bord-de-l-eau}">les enfants</a>, <a href="{blog:manger-boire-bronzer-avant-de-se-baigner}">manger, boire et bronzer</a>, <a href="{blog:plonger-sauter-eau-inconnue}">plonger dans l’inconnu</a>, <a href="{blog:matelas-pneumatiques-bouees-eau-profonde}">matelas et bouées</a>, <a href="{blog:nager-seul-eau-libre}">nager seul</a>.')]] },
    en: { titre: 'The six swimming safety rules of the Swiss Lifesaving Society', h1: 'The six swimming safety rules, explained', desc: 'Accompanied children, no alcohol or full or empty stomach, no jumping in after sunbathing, no diving into the unknown, no air mattress in deep water, never alone far out: the SLRG’s six rules.',
      bref: 'The <strong>Swiss Lifesaving Society (SLRG)</strong> sums up swimming in <strong>six rules</strong>: 1) children at the water’s edge are always accompanied; 2) no alcohol, no full or empty stomach; 3) no jumping in after prolonged sunbathing; 4) no diving or jumping into murky or unknown water; 5) no air mattresses in deep water; 6) never swim long distances alone.',
      s: [['The six rules', UL('<strong>1.</strong> Children at the water’s edge must always be accompanied; small children are kept within arm’s reach.', '<strong>2.</strong> Never swim after alcohol or drugs, or on a full or completely empty stomach.', '<strong>3.</strong> Never jump into the water after prolonged sunbathing: the body needs time to adapt.', '<strong>4.</strong> Do not dive or jump into murky or unknown water.', '<strong>5.</strong> Air mattresses and any swimming aids must not be used in deep water.', '<strong>6.</strong> Never swim long distances alone.')],
        ['Why these six?', P('The SLRG explains each rule on its page: small children can drown in under 20 seconds, silently, even in shallow water; alcohol impairs awareness and makes people overestimate themselves; the thermal shock after sunbathing can cause cramps, faintness, even fainting; unseen dangers hide in unknown water; a mattress can lose its air; even the best-trained body can fail.', 'We cover each in an article: <a href="{blog:enfants-au-bord-de-l-eau}">children</a>, <a href="{blog:manger-boire-bronzer-avant-de-se-baigner}">eating, drinking and sunbathing</a>, <a href="{blog:plonger-sauter-eau-inconnue}">diving into the unknown</a>, <a href="{blog:matelas-pneumatiques-bouees-eau-profonde}">mattresses and floats</a>, <a href="{blog:nager-seul-eau-libre}">swimming alone</a>.')]] },
    de: { titre: 'Die sechs Baderegeln der Schweizerischen Lebensrettungs-Gesellschaft', h1: 'Die sechs Baderegeln, erklärt', desc: 'Kinder begleiten, kein Alkohol und kein voller oder leerer Magen, kein Sprung nach dem Sonnenbad, kein Kopfsprung ins Unbekannte, keine Luftmatratze im tiefen Wasser, nie allein weit hinaus: die sechs Regeln der SLRG.',
      bref: 'Die <strong>Schweizerische Lebensrettungs-Gesellschaft (SLRG)</strong> fasst das Baden in <strong>sechs Regeln</strong> zusammen: 1) Kinder am Wasser immer begleiten; 2) kein Alkohol, nicht mit vollem oder leerem Magen; 3) nach langem Sonnenbad nicht ins Wasser springen; 4) nicht in trübes oder unbekanntes Wasser springen oder tauchen; 5) keine Luftmatratzen im tiefen Wasser; 6) nie allein lange Strecken schwimmen.',
      s: [['Die sechs Regeln', UL('<strong>1.</strong> Kinder am Wasser immer begleiten; kleine Kinder in Griffnähe halten.', '<strong>2.</strong> Nie nach Alkohol oder Drogen baden, nicht mit vollem und nicht mit ganz leerem Magen.', '<strong>3.</strong> Nach langem Sonnenbad nie ins Wasser springen: Der Körper braucht Zeit zur Anpassung.', '<strong>4.</strong> Nicht in trübes oder unbekanntes Wasser tauchen oder springen.', '<strong>5.</strong> Luftmatratzen und Schwimmhilfen nicht im tiefen Wasser verwenden.', '<strong>6.</strong> Nie allein lange Strecken schwimmen.')],
        ['Warum gerade diese sechs?', P('Die SLRG erklärt jede Regel auf ihrer Seite: Kleine Kinder können in weniger als 20 Sekunden ertrinken, lautlos, selbst in geringer Tiefe; Alkohol trübt das Bewusstsein und lässt die eigenen Fähigkeiten überschätzen; der Temperaturschock nach dem Sonnenbad kann Krämpfe, Unwohlsein, sogar Ohnmacht auslösen; im unbekannten Wasser lauern unsichtbare Gefahren; eine Matratze kann Luft verlieren; selbst der bestgeübte Körper kann versagen.', 'Jede behandeln wir in einem Artikel: <a href="{blog:enfants-au-bord-de-l-eau}">Kinder</a>, <a href="{blog:manger-boire-bronzer-avant-de-se-baigner}">Essen, Trinken und Sonnenbad</a>, <a href="{blog:plonger-sauter-eau-inconnue}">Sprung ins Unbekannte</a>, <a href="{blog:matelas-pneumatiques-bouees-eau-profonde}">Matratzen und Schwimmhilfen</a>, <a href="{blog:nager-seul-eau-libre}">allein schwimmen</a>.')]] },
    it: { titre: 'Le sei massime di balneazione della Società Svizzera di Salvataggio', h1: 'Le sei massime di balneazione, spiegate', desc: 'Bambini accompagnati, niente alcol né stomaco pieno o vuoto, niente tuffi dopo il sole, niente tuffi nell’ignoto, niente materassino in acqua profonda, mai soli lontano: le sei massime della SSS.',
      bref: 'La <strong>Società Svizzera di Salvataggio (SSS)</strong> riassume la balneazione in <strong>sei massime</strong>: 1) accompagnare i bambini in riva all’acqua; 2) niente alcol, né stomaco pieno né vuoto; 3) niente tuffi dopo un lungo bagno di sole; 4) niente tuffi in acque torbide o sconosciute; 5) niente materassini in acqua profonda; 6) mai nuotare da soli su lunghe distanze.',
      s: [['Le sei massime', UL('<strong>1.</strong> I bambini in riva all’acqua devono sempre essere accompagnati; i più piccoli si tengono a portata di mano.', '<strong>2.</strong> Mai fare il bagno dopo alcol o droghe, né a stomaco pieno né completamente vuoto.', '<strong>3.</strong> Mai tuffarsi dopo un lungo bagno di sole: il corpo ha bisogno di tempo per adattarsi.', '<strong>4.</strong> Non tuffarsi né saltare in acque torbide o sconosciute.', '<strong>5.</strong> Materassini e ausili al nuoto non vanno usati in acqua profonda.', '<strong>6.</strong> Mai nuotare da soli su lunghe distanze.')],
        ['Perché proprio queste sei?', P('La SSS spiega ogni massima nella sua pagina: i bambini piccoli possono annegare in meno di 20 secondi, in silenzio, anche in acqua bassa; l’alcol altera la coscienza e fa sopravvalutare le proprie capacità; lo shock termico dopo il sole può causare crampi, malessere, perfino svenimento; pericoli invisibili si nascondono nell’acqua sconosciuta; un materassino può perdere aria; anche il corpo meglio allenato può cedere.', 'Le approfondiamo ciascuna in un articolo: <a href="{blog:enfants-au-bord-de-l-eau}">i bambini</a>, <a href="{blog:manger-boire-bronzer-avant-de-se-baigner}">mangiare, bere e prendere il sole</a>, <a href="{blog:plonger-sauter-eau-inconnue}">tuffarsi nell’ignoto</a>, <a href="{blog:matelas-pneumatiques-bouees-eau-profonde}">materassini e galleggianti</a>, <a href="{blog:nager-seul-eau-libre}">nuotare da soli</a>.')]] } }),

  A('puces-de-canard-dermatite-du-baigneur', 'puces-canard', ['Un canard sur l’eau près d’un ponton, des herbiers clairs et peu profonds, une serviette posée sur un banc', 'A duck on the water near a jetty, pale shallow weeds, a towel on a bench', 'Eine Ente auf dem Wasser nahe einem Steg, helle flache Wasserpflanzen, ein Handtuch auf einer Bank', 'Un’anatra sull’acqua vicino a un molo, erbe acquatiche chiare e basse, un asciugamano su una panchina'], [OFSP, GE_PUCES], {
    fr: { titre: 'Puces de canard : la dermatite du baigneur, que faire et comment l’éviter', h1: 'Puces de canard : démangeaisons après la baignade', desc: 'Ce que sont les puces de canard (cercaires), les symptômes, ce qui aide, et comment réduire le risque, d’après l’Office fédéral de la santé publique et l’État de Genève.',
      bref: 'Les « puces de canard » sont des <strong>larves de parasites d’oiseaux d’eau</strong> (les cercaires) qui peuvent s’enfoncer sous la peau des baigneurs et causer une <strong>éruption allergique</strong>. Elle est en général sans gravité, peut durer plus d’une semaine, et n’est pas transmissible. Pour réduire le risque : se sécher énergiquement et se doucher dès la sortie de l’eau, éviter les eaux chaudes, peu profondes et riches en plantes.',
      s: [['Qu’est-ce que c’est ?', P('Selon la fiche de l’Office fédéral de la santé publique (OFSP), la dermatite du baigneur, ou dermatite cercarienne, est une éruption cutanée allergique causée par des parasites d’oiseaux (en Suisse surtout des canards) ou de mammifères aquatiques. Leurs larves infectent des escargots d’eau, qui les rejettent dans l’eau. Parfois, au lieu d’infecter un oiseau, elles s’infiltrent sous la peau d’un baigneur : elles ne peuvent pas s’y développer et meurent rapidement, mais la réaction allergique, elle, se déclenche.')],
        ['Quels symptômes ?', P('Picotements, brûlures et démangeaisons, qui peuvent apparaître quelques minutes à quelques jours après la baignade ; petites vésicules rouges dans les 12 heures, parfois de petites cloques. Gratter peut provoquer une infection bactérienne. Les irritations peuvent durer plus d’une semaine ; selon le canton de Genève, elles durent rarement jusqu’à un mois. Ce n’est en général pas une menace sérieuse pour la santé.')],
        ['Que faire ?', UL('Ne pas se gratter.', 'Appliquer des compresses froides (OFSP, Genève).', 'Un pharmacien peut conseiller un gel ou une lotion contre l’irritation ; l’OFSP cite aussi une crème à base de corticostéroïde sans ordonnance et, en cas de forte démangeaison, des antihistaminiques oraux.', 'Consulter un médecin en cas de symptômes très violents (vertiges, transpiration, fièvre, nausées) selon l’OFSP, ou si les symptômes persistent plus d’un mois selon Genève.')],
        ['Comment réduire le risque ?', UL('Se doucher à la sortie, se sécher énergiquement et tout de suite avec une serviette (OFSP, Genève). Les enfants sont plus touchés, parce qu’ils restent dans l’eau peu profonde et se sèchent moins.', 'Éviter de se baigner longuement dans les eaux chaudes, peu profondes et riches en plantes aquatiques ; les bons nageurs peuvent préférer des eaux plus profondes et plus froides (Genève).', 'Éviter les zones où des mises en garde existent (OFSP).'), P('Genève précise que les conditions favorables sont en principe une eau au-dessus de 20 °C, des herbiers et des canards, mais que ce n’est pas une règle absolue, que des cas se produisent sous 20 °C, et qu’aucune carte ne dit où se trouvent les cercaires : elles peuvent être dans tous les lieux de baignade lacustre. Aucun produit préventif ou répulsif n’est reconnu comme réellement efficace.')]] },
    en: { titre: 'Duck fleas: swimmer’s itch, what to do and how to avoid it', h1: 'Duck fleas: itching after a swim', desc: 'What duck fleas (cercariae) are, the symptoms, what helps, and how to reduce the risk, according to the Federal Office of Public Health and the canton of Geneva.',
      bref: '“Duck fleas” are <strong>larvae of waterbird parasites</strong> (cercariae) that can burrow under swimmers’ skin and cause an <strong>allergic rash</strong>. It is usually harmless, can last more than a week, and is not contagious. To reduce the risk: dry yourself vigorously and shower as soon as you leave the water, avoid warm, shallow, weedy water.',
      s: [['What is it?', P('According to the Federal Office of Public Health (FOPH) fact sheet, swimmer’s itch, or cercarial dermatitis, is an allergic skin rash caused by parasites of birds (in Switzerland mostly ducks) or aquatic mammals. Their larvae infect water snails, which release them into the water. Sometimes, instead of infecting a bird, they burrow under a swimmer’s skin: they cannot develop there and die quickly, but the allergic reaction is triggered.')],
        ['What are the symptoms?', P('Tingling, burning and itching, which can appear from a few minutes to a few days after swimming; small red blisters within 12 hours, sometimes small bubbles. Scratching can cause a bacterial infection. The irritation can last more than a week; according to the canton of Geneva, it rarely lasts up to a month. It is usually not a serious health threat.')],
        ['What to do?', UL('Do not scratch.', 'Apply cold compresses (FOPH, Geneva).', 'A pharmacist can advise a gel or lotion against irritation; the FOPH also cites an over-the-counter corticosteroid cream and, for severe itching, oral antihistamines.', 'See a doctor for very severe symptoms (dizziness, sweating, fever, nausea) according to the FOPH, or if symptoms last more than a month according to Geneva.')],
        ['How to reduce the risk?', UL('Shower when you get out, dry yourself vigorously and straight away with a towel (FOPH, Geneva). Children are affected more, because they stay in shallow water and dry off less.', 'Avoid long swims in warm, shallow water rich in aquatic plants; good swimmers may prefer deeper, colder water (Geneva).', 'Avoid areas with warnings (FOPH).'), P('Geneva notes that favourable conditions are in principle water above 20 °C, weeds and ducks, but that this is not an absolute rule, that cases occur below 20 °C, and that no map shows where cercariae are: they may be in every lake swimming spot. No preventive product or repellent is recognised as truly effective.')]] },
    de: { titre: 'Entenflöhe: die Badedermatitis, was tun und wie vorbeugen', h1: 'Entenflöhe: Juckreiz nach dem Baden', desc: 'Was Entenflöhe (Zerkarien) sind, die Symptome, was hilft und wie man das Risiko senkt, nach Bundesamt für Gesundheit und Kanton Genf.',
      bref: '«Entenflöhe» sind <strong>Larven von Wasservogel-Parasiten</strong> (Zerkarien), die unter die Haut von Badenden eindringen und einen <strong>allergischen Ausschlag</strong> auslösen können. Er ist in der Regel harmlos, kann über eine Woche dauern und ist nicht ansteckend. Risiko senken: nach dem Baden sofort kräftig abtrocknen und duschen, warme, flache, pflanzenreiche Gewässer meiden.',
      s: [['Was ist das?', P('Laut Merkblatt des Bundesamts für Gesundheit (BAG) ist die Badedermatitis oder Zerkariendermatitis ein allergischer Hautausschlag, ausgelöst durch Parasiten von Vögeln (in der Schweiz vor allem Enten) oder Wassersäugetieren. Ihre Larven befallen Wasserschnecken, die sie ins Wasser abgeben. Manchmal dringen sie, statt einen Vogel zu befallen, unter die Haut von Badenden ein: Sie können sich dort nicht entwickeln und sterben rasch, doch die allergische Reaktion wird ausgelöst.')],
        ['Welche Symptome?', P('Kribbeln, Brennen und Juckreiz, die wenige Minuten bis wenige Tage nach dem Baden auftreten können; kleine rote Bläschen innert 12 Stunden, manchmal kleine Blasen. Kratzen kann eine bakterielle Infektion auslösen. Die Reizungen können über eine Woche dauern; laut Kanton Genf dauern sie selten bis zu einem Monat. In der Regel keine ernste Gesundheitsgefahr.')],
        ['Was tun?', UL('Nicht kratzen.', 'Kalte Kompressen auflegen (BAG, Genf).', 'Eine Apothekerin oder ein Apotheker kann ein Gel oder eine Lotion gegen die Reizung empfehlen; das BAG nennt auch eine rezeptfreie Kortikosteroid-Creme und bei starkem Juckreiz orale Antihistaminika.', 'Bei sehr heftigen Symptomen (Schwindel, Schwitzen, Fieber, Übelkeit) laut BAG, oder wenn die Symptome laut Genf länger als einen Monat anhalten, zum Arzt.')],
        ['Wie senkt man das Risiko?', UL('Nach dem Baden duschen, sofort und kräftig mit einem Tuch abtrocknen (BAG, Genf). Kinder sind stärker betroffen, weil sie im flachen Wasser bleiben und sich weniger abtrocknen.', 'Lange Aufenthalte in warmem, flachem, pflanzenreichem Wasser vermeiden; gute Schwimmerinnen und Schwimmer können tieferes, kälteres Wasser vorziehen (Genf).', 'Gebiete mit Warnungen meiden (BAG).'), P('Genf hält fest, günstige Bedingungen seien grundsätzlich Wasser über 20 °C, Pflanzenbestände und Enten, aber das sei keine absolute Regel, Fälle gebe es auch unter 20 °C, und keine Karte zeige, wo Zerkarien vorkommen: Sie können an allen Badestellen am See sein. Kein vorbeugendes Mittel oder Repellent gilt als wirklich wirksam.')]] },
    it: { titre: 'Pulci d’anatra: la dermatite del bagnante, cosa fare e come evitarla', h1: 'Pulci d’anatra: prurito dopo il bagno', desc: 'Cosa sono le pulci d’anatra (cercarie), i sintomi, cosa aiuta e come ridurre il rischio, secondo l’Ufficio federale della sanità pubblica e il Cantone di Ginevra.',
      bref: 'Le «pulci d’anatra» sono <strong>larve di parassiti degli uccelli acquatici</strong> (cercarie) che possono penetrare sotto la pelle dei bagnanti e causare un’<strong>eruzione allergica</strong>. Di solito è senza gravità, può durare più di una settimana e non è contagiosa. Per ridurre il rischio: asciugarsi energicamente e fare la doccia appena usciti dall’acqua, evitare acque calde, basse e ricche di piante.',
      s: [['Che cos’è?', P('Secondo la scheda dell’Ufficio federale della sanità pubblica (UFSP), la dermatite del bagnante, o dermatite da cercarie, è un’eruzione cutanea allergica causata da parassiti di uccelli (in Svizzera soprattutto anatre) o di mammiferi acquatici. Le loro larve infettano le lumache d’acqua, che le rilasciano nell’acqua. A volte, invece di infettare un uccello, penetrano sotto la pelle di un bagnante: non possono svilupparsi e muoiono presto, ma la reazione allergica si scatena.')],
        ['Quali sintomi?', P('Formicolio, bruciore e prurito, che possono comparire da pochi minuti a pochi giorni dopo il bagno; piccole vescicole rosse entro 12 ore, a volte piccole bolle. Grattarsi può provocare un’infezione batterica. Le irritazioni possono durare più di una settimana; secondo il Cantone di Ginevra raramente fino a un mese. Di solito non è una minaccia seria per la salute.')],
        ['Cosa fare?', UL('Non grattarsi.', 'Applicare impacchi freddi (UFSP, Ginevra).', 'Un farmacista può consigliare un gel o una lozione contro l’irritazione; l’UFSP cita anche una crema a base di corticosteroidi senza ricetta e, in caso di forte prurito, antistaminici orali.', 'Rivolgersi a un medico in caso di sintomi molto violenti (vertigini, sudorazione, febbre, nausea) secondo l’UFSP, o se i sintomi durano più di un mese secondo Ginevra.')],
        ['Come ridurre il rischio?', UL('Fare la doccia all’uscita, asciugarsi energicamente e subito con un asciugamano (UFSP, Ginevra). I bambini sono più colpiti, perché restano in acqua bassa e si asciugano meno.', 'Evitare bagni lunghi in acque calde, basse e ricche di piante acquatiche; i buoni nuotatori possono preferire acque più profonde e fredde (Ginevra).', 'Evitare le zone con avvisi (UFSP).'), P('Ginevra precisa che le condizioni favorevoli sono in linea di principio acqua sopra i 20 °C, erbai e anatre, ma che non è una regola assoluta, che casi si verificano anche sotto i 20 °C, e che nessuna mappa dice dove si trovino le cercarie: possono essere in tutti i luoghi di balneazione lacustre. Nessun prodotto preventivo o repellente è riconosciuto come davvero efficace.')]] } }),

  A('cyanobacteries-baignade-lac', 'cyanobacteries', ['Un lac vert-turquoise trouble près d’une plage, des traînées sur l’eau, un panneau jaune vierge sur un piquet', 'A cloudy turquoise-green lake by a beach, streaks on the water, a blank yellow sign on a post', 'Ein trüber türkisgrüner See an einem Strand, Schlieren auf dem Wasser, ein leeres gelbes Schild an einem Pfosten', 'Un lago torbido verde-turchese vicino a una spiaggia, striature sull’acqua, un cartello giallo vuoto su un palo'], [VD_CYANO], {
    fr: { titre: 'Cyanobactéries dans les lacs : les recommandations du canton de Vaud', h1: 'Cyanobactéries : reconnaître une prolifération, que faire', desc: 'À quoi ressemble une prolifération de cyanobactéries, quels effets sur l’humain et le chien, et les conseils du canton de Vaud : éviter l’eau, se doucher, garder les animaux hors du lac.',
      bref: 'Une prolifération de <strong>cyanobactéries</strong> se reconnaît à une <strong>couche colorée et trouble</strong> (vert-turquoise, rougeâtre, brun-jaune) ou à des <strong>amas spongieux flottants</strong>. Le canton de Vaud recommande alors d’<strong>éviter la baignade</strong> et de ne pas laisser les animaux boire ni se baigner. Chez le chien, l’ingestion de toxines peut être mortelle ; chez l’humain, les effets s’apparentent le plus souvent à des symptômes gastro-intestinaux.',
      s: [['Comment les reconnaître ?', P('Selon le canton de Vaud, les proliférations apparaissent souvent en quelques jours et disparaissent aussi vite. Elles prennent la forme de traînées ou de tapis spongieux et gluants qui flottent à la surface, parfois de dépôts sur la berge, et peuvent dégager des odeurs désagréables. Signes d’alerte : une couche colorée (vert-turquoise, rougeâtre, brun-jaune) et trouble, où le fond n’est pas visible à faible profondeur.')],
        ['Quels effets ?', P('En cas d’ingestion, des toxines de certaines espèces peuvent entraîner la mort d’animaux de compagnie comme les chiens. Chez l’humain, les effets s’apparentent à des symptômes gastro-intestinaux (maux de ventre, diarrhée, vomissements), voire à un état grippal (fièvre, maux de tête et de gorge, douleurs articulaires) ; en cas de contact, les toxines peuvent irriter la peau et les muqueuses. La plupart du temps les effets sont bénins, mais les jeunes enfants sont davantage concernés, car ils sont plus exposés durant la baignade. Le canton relève que ces proliférations nuisibles sont relativement rares.')],
        ['Que faire ?', UL('Éviter que les jeunes enfants boivent l’eau du lac ou portent à la bouche des galets de la plage.', 'Se doucher après la baignade et se sécher soigneusement.', 'Si vous voyez une couche colorée et trouble ou des amas spongieux : éviter la baignade et les activités en contact avec l’eau.', 'En cas de symptômes après un contact suspect : contacter son médecin traitant ou la Centrale téléphonique des médecins de garde (0848 133 133).', 'Ne pas laisser les animaux se baigner ni s’abreuver ; en cas de suspicion d’intoxication (diarrhée, vomissements, tremblements ou difficulté respiratoire chez le chien), aller sans délai chez un vétérinaire.')],
        ['Et la qualité de l’eau ?', P('Le canton note qu’identifier ces micro-organismes et évaluer leur dangerosité en temps réel sur toutes les plages est difficile : la prudence doit prévaloir quand le phénomène apparaît. Pour les analyses bactériologiques, voir <a href="{blog:qualite-eau-baignade-leman}">comment vérifier la qualité de l’eau</a>.')]] },
    en: { titre: 'Cyanobacteria in lakes: the canton of Vaud’s recommendations', h1: 'Cyanobacteria: recognising a bloom, what to do', desc: 'What a cyanobacteria bloom looks like, the effects on people and dogs, and the canton of Vaud’s advice: avoid the water, shower, keep animals out of the lake.',
      bref: 'A <strong>cyanobacteria</strong> bloom shows as a <strong>coloured, cloudy layer</strong> (turquoise-green, reddish, yellow-brown) or <strong>floating spongy clumps</strong>. The canton of Vaud then recommends <strong>avoiding swimming</strong> and not letting animals drink or swim. In dogs, ingesting toxins can be fatal; in people, effects most often resemble gastrointestinal symptoms.',
      s: [['How to recognise them', P('According to the canton of Vaud, blooms often appear within days and vanish as fast. They take the form of streaks or spongy, sticky mats floating on the surface, sometimes deposits on the shore, and may give off unpleasant smells. Warning signs: a coloured (turquoise-green, reddish, yellow-brown) and cloudy layer, where the bottom is not visible in shallow water.')],
        ['What effects?', P('If swallowed, toxins from some species can kill pets such as dogs. In people, effects resemble gastrointestinal symptoms (stomach ache, diarrhoea, vomiting), even flu-like illness (fever, headache and sore throat, joint pain); on contact, toxins can irritate skin and mucous membranes. Most of the time effects are mild, but young children are more affected, as they are more exposed while swimming. The canton notes that harmful blooms are relatively rare.')],
        ['What to do', UL('Stop young children from drinking lake water or putting beach pebbles in their mouths.', 'Shower after swimming and dry yourself thoroughly.', 'If you see a coloured, cloudy layer or spongy clumps: avoid swimming and activities in contact with the water.', 'If symptoms appear after suspect contact: contact your doctor or the on-call doctors’ line (0848 133 133).', 'Do not let animals swim or drink; if poisoning is suspected (in dogs: diarrhoea, vomiting, tremors or breathing difficulty), go to a vet without delay.')],
        ['And water quality?', P('The canton notes that identifying these micro-organisms and assessing their danger in real time on every beach is difficult: caution must prevail when the phenomenon appears. For bacteriological analyses, see <a href="{blog:qualite-eau-baignade-leman}">how to check water quality</a>.')]] },
    de: { titre: 'Cyanobakterien in Seen: die Empfehlungen des Kantons Waadt', h1: 'Cyanobakterien: eine Blüte erkennen, was tun', desc: 'Wie eine Cyanobakterienblüte aussieht, welche Wirkungen auf Mensch und Hund und die Ratschläge des Kantons Waadt: Wasser meiden, duschen, Tiere vom See fernhalten.',
      bref: 'Eine <strong>Cyanobakterien</strong>-Blüte erkennt man an einer <strong>farbigen, trüben Schicht</strong> (türkisgrün, rötlich, gelbbraun) oder an <strong>schwimmenden, schwammigen Klumpen</strong>. Der Kanton Waadt empfiehlt dann, <strong>nicht zu baden</strong> und Tiere weder trinken noch baden zu lassen. Bei Hunden kann die Aufnahme von Toxinen tödlich sein; beim Menschen ähneln die Wirkungen meist Magen-Darm-Beschwerden.',
      s: [['Wie erkennt man sie?', P('Laut Kanton Waadt treten Blüten oft innert Tagen auf und verschwinden ebenso schnell. Sie bilden Schlieren oder schwammige, klebrige Teppiche an der Oberfläche, manchmal Ablagerungen am Ufer, und können unangenehm riechen. Warnzeichen: eine farbige (türkisgrün, rötlich, gelbbraun) und trübe Schicht, bei der man in geringer Tiefe den Grund nicht sieht.')],
        ['Welche Wirkungen?', P('Bei Aufnahme können Toxine einiger Arten Haustiere wie Hunde töten. Beim Menschen ähneln die Wirkungen Magen-Darm-Beschwerden (Bauchweh, Durchfall, Erbrechen), sogar grippeähnlichen Zuständen (Fieber, Kopf- und Halsschmerzen, Gelenkschmerzen); bei Kontakt können die Toxine Haut und Schleimhäute reizen. Meist sind die Wirkungen harmlos, doch kleine Kinder sind stärker betroffen, da sie beim Baden stärker exponiert sind. Der Kanton hält fest, schädliche Blüten seien relativ selten.')],
        ['Was tun?', UL('Verhindern, dass kleine Kinder Seewasser trinken oder Kiesel vom Strand in den Mund nehmen.', 'Nach dem Baden duschen und gründlich abtrocknen.', 'Bei farbiger, trüber Schicht oder schwammigen Klumpen: nicht baden und Aktivitäten mit Wasserkontakt meiden.', 'Bei Symptomen nach verdächtigem Kontakt: Hausärztin oder Hausarzt oder die ärztliche Notrufzentrale (0848 133 133) kontaktieren.', 'Tiere weder baden noch trinken lassen; bei Verdacht auf Vergiftung (beim Hund Durchfall, Erbrechen, Zittern oder Atemnot) sofort zur Tierärztin oder zum Tierarzt.')],
        ['Und die Wasserqualität?', P('Der Kanton hält fest, diese Mikroorganismen zu erkennen und ihre Gefährlichkeit an allen Stränden in Echtzeit zu beurteilen, sei schwierig: Vorsicht müsse walten, wenn das Phänomen auftritt. Zu bakteriologischen Analysen siehe <a href="{blog:qualite-eau-baignade-leman}">Wasserqualität prüfen</a>.')]] },
    it: { titre: 'Cianobatteri nei laghi: le raccomandazioni del Cantone di Vaud', h1: 'Cianobatteri: riconoscere una fioritura, cosa fare', desc: 'Che aspetto ha una fioritura di cianobatteri, gli effetti su persone e cani e i consigli del Cantone di Vaud: evitare l’acqua, fare la doccia, tenere gli animali fuori dal lago.',
      bref: 'Una fioritura di <strong>cianobatteri</strong> si riconosce da uno <strong>strato colorato e torbido</strong> (verde-turchese, rossastro, giallo-bruno) o da <strong>ammassi spugnosi galleggianti</strong>. Il Cantone di Vaud raccomanda allora di <strong>evitare il bagno</strong> e di non lasciare bere né fare il bagno agli animali. Nel cane l’ingestione di tossine può essere mortale; nell’uomo gli effetti somigliano per lo più a sintomi gastrointestinali.',
      s: [['Come riconoscerli', P('Secondo il Cantone di Vaud, le fioriture compaiono spesso in pochi giorni e scompaiono altrettanto in fretta. Hanno forma di striature o tappeti spugnosi e viscidi che galleggiano in superficie, a volte depositi sulla riva, e possono emanare odori sgradevoli. Segnali d’allarme: uno strato colorato (verde-turchese, rossastro, giallo-bruno) e torbido, in cui a bassa profondità non si vede il fondo.')],
        ['Quali effetti?', P('In caso di ingestione, le tossine di alcune specie possono causare la morte di animali domestici come i cani. Nell’uomo gli effetti somigliano a sintomi gastrointestinali (mal di pancia, diarrea, vomito), perfino a uno stato influenzale (febbre, mal di testa e di gola, dolori articolari); a contatto, le tossine possono irritare pelle e mucose. Per lo più gli effetti sono lievi, ma i bambini piccoli sono più interessati, perché più esposti durante il bagno. Il Cantone osserva che le fioriture nocive sono relativamente rare.')],
        ['Cosa fare', UL('Evitare che i bambini piccoli bevano l’acqua del lago o mettano in bocca i ciottoli della spiaggia.', 'Fare la doccia dopo il bagno e asciugarsi con cura.', 'Se si vede uno strato colorato e torbido o ammassi spugnosi: evitare il bagno e le attività a contatto con l’acqua.', 'In caso di sintomi dopo un contatto sospetto: contattare il proprio medico o la centrale telefonica dei medici di guardia (0848 133 133).', 'Non lasciare gli animali fare il bagno né abbeverarsi; in caso di sospetto avvelenamento (nel cane diarrea, vomito, tremori o difficoltà respiratorie) andare subito dal veterinario.')],
        ['E la qualità dell’acqua?', P('Il Cantone nota che identificare questi microrganismi e valutarne la pericolosità in tempo reale su tutte le spiagge è difficile: la prudenza deve prevalere quando il fenomeno compare. Per le analisi batteriologiche, vedi <a href="{blog:qualite-eau-baignade-leman}">come verificare la qualità dell’acqua</a>.')]] } }),

  A('feux-de-tempete-leman', 'feux-tempete', ['Un phare de port avec un feu orange au sommet d’un mât, le lac sous un ciel qui se couvre', 'A harbour light with an orange lamp atop a mast, the lake under a darkening sky', 'Ein Hafenfeuer mit orangem Licht auf einem Mast, der See unter sich bewölkendem Himmel', 'Un faro di porto con una luce arancione in cima a un palo, il lago sotto un cielo che si copre'], [VD_FEUX], {
    fr: { titre: 'Feux de tempête sur le Léman : à quoi servent les feux à éclipses', h1: 'Les feux à éclipses du Léman : un signal de vent fort ou de tempête', desc: 'Installés sur les rives du Léman, de Neuchâtel et de Morat, les feux à éclipses avertissent d’un fort vent ou d’une tempête. Qui les enclenche, qui doit y prêter attention, d’après l’État de Vaud.',
      bref: 'Les <strong>feux à éclipses</strong> sont des <strong>feux d’alerte</strong> installés sur les rives du Léman, de Neuchâtel et de Morat. Ils s’enclenchent à partir des <strong>avis de fort vent ou de tempête de MétéoSuisse</strong> et s’adressent aux personnes qui naviguent, pratiquent des sports nautiques, se baignent ou sont sur les quais. Le dispositif compte 36 sites, dont 20 sous responsabilité vaudoise.',
      s: [['À quoi servent-ils ?', P('D’après l’État de Vaud, les feux à éclipses sont des signaux d’alerte visibles et immédiatement compréhensibles, installés aux abords des ports et sur les rives. Ils avertissent la population en cas de fort vent ou de tempête, et s’adressent aux personnes qui naviguent, pratiquent des sports nautiques, se baignent, ou sont présentes sur les quais et les rives, ainsi qu’à d’autres usagers concernés par la météo, comme les parapentistes.')],
        ['Qui les déclenche ?', P('Le système d’enclenchement repose sur les avis de fort vent ou de tempête de l’Office fédéral de météorologie et climatologie MétéoSuisse. Les installations peuvent désormais être surveillées à distance et en temps réel, ce qui permet de détecter plus vite une panne et de vérifier que les avis transmis par MétéoSuisse ont bien été exécutés.')],
        ['Où sont-ils ?', P('Le renouvellement des feux, achevé, concerne 36 sites, dont 20 sous responsabilité vaudoise, sur les lacs Léman, de Neuchâtel et de Morat. Il a été coordonné par le canton de Vaud avec les cantons riverains (Vaud, Neuchâtel, Fribourg, Genève, Valais) et la Haute-Savoie, où cinq feux se trouvent sur la rive française du Léman.')],
        ['Ce que nous ne détaillons pas', P('Le canton ne précise pas, dans son communiqué, la cadence de clignotement ni la signification de chaque signal. Pour les connaître, consultez MétéoSuisse ou la police du lac avant de partir. Ces feux complètent d’autres canaux d’information, notamment numériques, comme <a href="{blog:vents-du-leman}">les vents du Léman</a> et <a href="{app}">l’app</a>.')]] },
    en: { titre: 'Storm lights on Lake Geneva: what the flashing beacons are for', h1: 'Lake Geneva’s flashing beacons: a strong-wind or storm signal', desc: 'Installed on the shores of Lake Geneva, Neuchâtel and Murten, the flashing beacons warn of strong wind or a storm. Who triggers them and who should heed them, according to the canton of Vaud.',
      bref: 'The <strong>flashing beacons</strong> (<em>feux à éclipses</em>) are <strong>warning lights</strong> installed on the shores of Lakes Geneva, Neuchâtel and Murten. They switch on from <strong>MeteoSwiss strong-wind or storm warnings</strong> and are aimed at boaters, water-sports people, swimmers and people on the quays. The system has 36 sites, 20 under Vaud responsibility.',
      s: [['What are they for?', P('According to the canton of Vaud, the beacons are visible, immediately understandable warning signals installed around ports and on shores. They warn the public of strong wind or a storm, and are aimed at people who sail, do water sports, swim, or are on quays and shores, as well as other users affected by the weather, such as paragliders.')],
        ['Who triggers them?', P('The switching system is based on strong-wind or storm warnings from the Federal Office of Meteorology and Climatology MeteoSwiss. The installations can now be monitored remotely and in real time, which makes it possible to detect a fault sooner and to check that MeteoSwiss warnings have actually been carried out.')],
        ['Where are they?', P('The completed renewal covers 36 sites, 20 under Vaud responsibility, on Lakes Geneva, Neuchâtel and Murten. It was coordinated by the canton of Vaud with the riparian cantons (Vaud, Neuchâtel, Fribourg, Geneva, Valais) and Haute-Savoie, where five beacons stand on the French shore of Lake Geneva.')],
        ['What we do not detail', P('The canton’s press release does not state the flashing rate or the meaning of each signal. To learn them, check MeteoSwiss or the lake police before heading out. The beacons complement other information channels, including digital ones, such as <a href="{blog:vents-du-leman}">the winds of Lake Geneva</a> and <a href="{app}">the app</a>.')]] },
    de: { titre: 'Sturmwarnlichter am Genfersee: wofür die Blinkfeuer da sind', h1: 'Die Blinkfeuer des Genfersees: ein Signal für starken Wind oder Sturm', desc: 'An den Ufern von Genfer-, Neuenburger- und Murtensee warnen die Blinkfeuer vor starkem Wind oder Sturm. Wer sie auslöst und wer darauf achten soll, nach dem Kanton Waadt.',
      bref: 'Die <strong>Blinkfeuer</strong> (<em>feux à éclipses</em>) sind <strong>Warnlichter</strong> an den Ufern von Genfer-, Neuenburger- und Murtensee. Sie werden aufgrund der <strong>Warnungen vor starkem Wind oder Sturm von MeteoSchweiz</strong> eingeschaltet und richten sich an Schiffende, Wassersportler, Badende und Personen an den Kais. Das System umfasst 36 Standorte, 20 davon in Waadtländer Verantwortung.',
      s: [['Wofür sind sie da?', P('Laut Kanton Waadt sind die Blinkfeuer sichtbare, sofort verständliche Warnsignale bei den Häfen und an den Ufern. Sie warnen die Bevölkerung vor starkem Wind oder Sturm und richten sich an Personen, die segeln, Wassersport treiben, baden oder auf Kais und Ufern sind, sowie an weitere vom Wetter betroffene Nutzende wie Gleitschirmpiloten.')],
        ['Wer löst sie aus?', P('Das Einschaltsystem beruht auf den Warnungen vor starkem Wind oder Sturm des Bundesamts für Meteorologie und Klimatologie MeteoSchweiz. Die Anlagen können nun aus der Ferne und in Echtzeit überwacht werden, was erlaubt, eine Störung schneller zu erkennen und zu prüfen, ob die Warnungen von MeteoSchweiz tatsächlich ausgeführt wurden.')],
        ['Wo stehen sie?', P('Die abgeschlossene Erneuerung betrifft 36 Standorte, 20 davon in Waadtländer Verantwortung, an Genfer-, Neuenburger- und Murtensee. Sie wurde vom Kanton Waadt mit den Anliegerkantonen (Waadt, Neuenburg, Freiburg, Genf, Wallis) und Haute-Savoie koordiniert, wo fünf Feuer am französischen Genferseeufer stehen.')],
        ['Was wir nicht ausführen', P('Die Medienmitteilung des Kantons nennt weder die Blinkfrequenz noch die Bedeutung der einzelnen Signale. Um sie zu erfahren, vor der Abfahrt MeteoSchweiz oder die Seepolizei konsultieren. Die Feuer ergänzen andere Informationskanäle, auch digitale, wie <a href="{blog:vents-du-leman}">die Winde des Genfersees</a> und <a href="{app}">die App</a>.')]] },
    it: { titre: 'Fuochi di tempesta sul Lemano: a cosa servono i fari lampeggianti', h1: 'I fari lampeggianti del Lemano: un segnale di vento forte o tempesta', desc: 'Installati sulle rive del Lemano, di Neuchâtel e di Morat, i fari lampeggianti avvertono di vento forte o tempesta. Chi li attiva e chi deve farci attenzione, secondo il Cantone di Vaud.',
      bref: 'I <strong>fari lampeggianti</strong> (<em>feux à éclipses</em>) sono <strong>luci d’allarme</strong> installate sulle rive del Lemano, di Neuchâtel e di Morat. Si accendono in base agli <strong>avvisi di vento forte o tempesta di MeteoSvizzera</strong> e si rivolgono a chi naviga, pratica sport nautici, fa il bagno o si trova sui moli. Il dispositivo conta 36 siti, 20 sotto responsabilità vodese.',
      s: [['A cosa servono?', P('Secondo il Cantone di Vaud, i fari sono segnali d’allarme visibili e immediatamente comprensibili, installati vicino ai porti e sulle rive. Avvertono la popolazione in caso di vento forte o tempesta e si rivolgono a chi naviga, pratica sport nautici, fa il bagno o si trova su moli e rive, oltre ad altri utenti interessati dal meteo, come i parapendisti.')],
        ['Chi li attiva?', P('Il sistema di accensione si basa sugli avvisi di vento forte o tempesta dell’Ufficio federale di meteorologia e climatologia MeteoSvizzera. Gli impianti possono ora essere monitorati a distanza e in tempo reale, il che permette di rilevare prima un guasto e di verificare che gli avvisi di MeteoSvizzera siano stati eseguiti.')],
        ['Dove sono?', P('Il rinnovo, concluso, riguarda 36 siti, 20 sotto responsabilità vodese, sui laghi Lemano, di Neuchâtel e di Morat. È stato coordinato dal Cantone di Vaud con i cantoni rivieraschi (Vaud, Neuchâtel, Friburgo, Ginevra, Vallese) e l’Alta Savoia, dove cinque fari si trovano sulla riva francese del Lemano.')],
        ['Cosa non dettagliamo', P('Il comunicato del Cantone non precisa la cadenza del lampeggio né il significato di ogni segnale. Per conoscerli, consultate MeteoSvizzera o la polizia del lago prima di partire. I fari completano altri canali d’informazione, anche digitali, come <a href="{blog:vents-du-leman}">i venti del Lemano</a> e <a href="{app}">l’app</a>.')]] } }),

  A('enfants-au-bord-de-l-eau', 'enfants', ['Un seau, une pelle et de petits souliers au bord de l’eau peu profonde, un adulte hors cadre', 'A bucket, a spade and small shoes at the edge of shallow water, an adult out of frame', 'Ein Eimer, eine Schaufel und kleine Schuhe am Rand des flachen Wassers, ein Erwachsener ausserhalb des Bildes', 'Un secchiello, una paletta e scarpine al bordo dell’acqua bassa, un adulto fuori campo'], [BAIGNADE, FAMILLES], {
    fr: { titre: 'Enfants au bord de l’eau : ce que recommande la Société Suisse de Sauvetage', h1: 'Enfants au bord de l’eau : surveiller à portée de main', desc: 'Pourquoi les petits enfants se noient en silence, ce que valent brassards et gilets, et les conseils de la SSS pour les familles.',
      bref: 'Selon la <strong>Société Suisse de Sauvetage (SSS)</strong>, les petits enfants peuvent se noyer <strong>en moins de 20 secondes</strong>, même dans une faible profondeur, et <strong>sans bruit</strong>. Elle demande de les garder à portée de main et de ne pas se laisser distraire par le smartphone. Brassards et animaux gonflables <strong>ne remplacent pas la surveillance</strong> ; elle recommande un gilet de sauvetage.',
      s: [['Pourquoi les petits enfants sont-ils plus exposés ?', P('La SSS explique que leur centre de gravité est plus haut que celui des adultes : la tête lourde entraîne l’enfant vers l’avant et vers le bas, et même une faible profondeur peut mettre la vie en danger. Ils se noient en silence, n’ont pas encore le sens de l’orientation sous l’eau et, jusqu’à environ trois ans, pas la force de garder la tête hors de l’eau. La noyade est la deuxième cause la plus fréquente de décès accidentel chez les enfants.')],
        ['Que faire ?', UL('Garder les petits enfants à portée de main, et ne pas se laisser distraire par le smartphone ou une conversation (première maxime de la SSS).', 'Ne jamais considérer brassards ou animaux gonflables comme une surveillance : ils peuvent glisser, être défectueux ou placer l’enfant dans une situation dangereuse.', 'Si on veut une aide : la SSS recommande un gilet de sauvetage, qui offre une flottabilité constante et se fixe mieux que des brassards.', 'Protéger un biotope ou une piscine privée de la curiosité des jeunes enfants, par exemple par une clôture dont la porte se ferme et se verrouille automatiquement.', 'Familiariser tôt l’enfant avec l’eau, sous forme de jeux, avec conseils et surveillance.')],
        ['Quel gilet choisir ?', P('Selon la SSS : un gilet de sauvetage et non une veste de natation (le gilet peut assurer la sécurité d’une personne inconsciente), à la taille du poids et de la taille de l’enfant, avec une sangle d’entrejambe pour qu’il ne remonte pas, de couleur voyante si possible. Les brassards offrent une flottabilité immédiate qui gagne de précieuses secondes, mais ils peuvent glisser ou se rompre, et la flottabilité uniquement aux bras est défavorable aux petits enfants.')]] },
    en: { titre: 'Children at the water’s edge: what the Swiss Lifesaving Society recommends', h1: 'Children at the water’s edge: supervise within reach', desc: 'Why small children drown silently, what armbands and life jackets are worth, and the SLRG’s advice for families.',
      bref: 'According to the <strong>Swiss Lifesaving Society (SLRG)</strong>, small children can drown <strong>in under 20 seconds</strong>, even in shallow water, and <strong>silently</strong>. It asks you to keep them within arm’s reach and not to be distracted by your phone. Armbands and inflatable animals <strong>do not replace supervision</strong>; it recommends a life jacket.',
      s: [['Why are small children more at risk?', P('The SLRG explains that their centre of gravity is higher than adults’: the heavy head pulls the child forward and down, and even shallow water can be life-threatening. They drown silently, do not yet have a sense of direction underwater and, until about age three, lack the strength to keep their head above water. Drowning is the second most frequent cause of accidental death in children.')],
        ['What to do', UL('Keep small children within arm’s reach, and do not be distracted by your phone or a conversation (the SLRG’s first rule).', 'Never treat armbands or inflatable animals as supervision: they can slip off, be faulty or put the child in a dangerous situation.', 'If you want an aid: the SLRG recommends a life jacket, which gives constant buoyancy and fastens better than armbands.', 'Protect a biotope or private pool from small children’s curiosity, for example with a fence whose gate closes and locks automatically.', 'Familiarise the child with water early, through play, with advice and supervision.')],
        ['Which life jacket?', P('According to the SLRG: a life jacket and not a swim vest (a life jacket can keep an unconscious person safe), sized to the child’s weight and height, with a crotch strap so it cannot ride up, in a bright colour if possible. Armbands give immediate buoyancy that buys precious seconds, but they can slip or burst, and buoyancy only at the arms is unfavourable for small children.')]] },
    de: { titre: 'Kinder am Wasser: was die Schweizerische Lebensrettungs-Gesellschaft empfiehlt', h1: 'Kinder am Wasser: in Griffnähe beaufsichtigen', desc: 'Warum kleine Kinder lautlos ertrinken, was Schwimmflügel und Schwimmwesten taugen und die Ratschläge der SLRG für Familien.',
      bref: 'Laut der <strong>Schweizerischen Lebensrettungs-Gesellschaft (SLRG)</strong> können kleine Kinder <strong>in weniger als 20 Sekunden</strong> ertrinken, selbst in geringer Tiefe, und <strong>lautlos</strong>. Sie bittet, sie in Griffnähe zu halten und sich nicht vom Smartphone ablenken zu lassen. Schwimmflügel und aufblasbare Tiere <strong>ersetzen die Aufsicht nicht</strong>; sie empfiehlt eine Rettungsweste.',
      s: [['Warum sind kleine Kinder stärker gefährdet?', P('Die SLRG erklärt, ihr Körperschwerpunkt liege höher als bei Erwachsenen: Der schwere Kopf zieht das Kind nach vorn und unten, und selbst geringe Wassertiefe kann lebensgefährlich sein. Sie ertrinken lautlos, haben unter Wasser noch keinen Orientierungssinn und bis etwa drei Jahre nicht die Kraft, den Kopf über Wasser zu halten. Ertrinken ist die zweithäufigste Ursache tödlicher Unfälle bei Kindern.')],
        ['Was tun?', UL('Kleine Kinder in Griffnähe halten und sich nicht von Smartphone oder Gespräch ablenken lassen (erste Baderegel der SLRG).', 'Schwimmflügel oder aufblasbare Tiere nie als Aufsicht betrachten: Sie können abrutschen, defekt sein oder das Kind in Gefahr bringen.', 'Wenn eine Hilfe gewünscht ist: Die SLRG empfiehlt eine Rettungsweste, die konstanten Auftrieb bietet und besser sitzt als Schwimmflügel.', 'Biotop oder privaten Pool vor der Neugier kleiner Kinder schützen, zum Beispiel mit einem Zaun, dessen Tür selbsttätig schliesst und verriegelt.', 'Das Kind früh spielerisch ans Wasser gewöhnen, mit Anleitung und Aufsicht.')],
        ['Welche Weste?', P('Laut SLRG: eine Rettungsweste und keine Schwimmweste (die Rettungsweste kann eine bewusstlose Person sichern), passend zu Gewicht und Grösse des Kindes, mit Schrittgurt, damit sie nicht hochrutscht, wenn möglich in Signalfarbe. Schwimmflügel bieten sofortigen Auftrieb, der kostbare Sekunden gewinnt, können aber abrutschen oder platzen, und Auftrieb nur an den Armen ist für Kleinkinder ungünstig.')]] },
    it: { titre: 'Bambini in riva all’acqua: cosa raccomanda la Società Svizzera di Salvataggio', h1: 'Bambini in riva all’acqua: sorvegliare a portata di mano', desc: 'Perché i bambini piccoli annegano in silenzio, quanto valgono braccioli e giubbotti e i consigli della SSS per le famiglie.',
      bref: 'Secondo la <strong>Società Svizzera di Salvataggio (SSS)</strong>, i bambini piccoli possono annegare <strong>in meno di 20 secondi</strong>, anche in acqua bassa, e <strong>in silenzio</strong>. Chiede di tenerli a portata di mano e di non farsi distrarre dallo smartphone. Braccioli e animali gonfiabili <strong>non sostituiscono la sorveglianza</strong>; raccomanda un giubbotto di salvataggio.',
      s: [['Perché i bambini piccoli sono più esposti?', P('La SSS spiega che il loro baricentro è più alto di quello degli adulti: la testa pesante trascina il bambino in avanti e verso il basso, e anche una profondità minima può essere pericolosa. Annegano in silenzio, non hanno ancora il senso dell’orientamento sott’acqua e, fino a circa tre anni, non hanno la forza di tenere la testa fuori dall’acqua. L’annegamento è la seconda causa più frequente di morte accidentale nei bambini.')],
        ['Cosa fare', UL('Tenere i bambini piccoli a portata di mano e non farsi distrarre da smartphone o conversazioni (prima massima della SSS).', 'Non considerare mai braccioli o animali gonfiabili come sorveglianza: possono scivolare, essere difettosi o mettere il bambino in pericolo.', 'Se si vuole un ausilio: la SSS raccomanda un giubbotto di salvataggio, che dà galleggiabilità costante e si fissa meglio dei braccioli.', 'Proteggere un biotopo o una piscina privata dalla curiosità dei bambini piccoli, per esempio con una recinzione il cui cancello si chiuda e blocchi automaticamente.', 'Far familiarizzare presto il bambino con l’acqua, giocando, con consigli e sorveglianza.')],
        ['Quale giubbotto?', P('Secondo la SSS: un giubbotto di salvataggio e non un giubbotto da nuoto (il giubbotto di salvataggio può proteggere una persona incosciente), adatto a peso e altezza del bambino, con sottogamba perché non risalga, possibilmente di colore vistoso. I braccioli danno galleggiabilità immediata che guadagna secondi preziosi, ma possono scivolare o rompersi, e la galleggiabilità solo alle braccia è sfavorevole ai bambini piccoli.')]] } }),

  A('manger-boire-bronzer-avant-de-se-baigner', 'repas-soleil', ['Une serviette, un panier de pique-nique fermé et un verre d’eau sur un ponton, le soleil haut sur le lac', 'A towel, a closed picnic basket and a glass of water on a jetty, the sun high over the lake', 'Ein Handtuch, ein geschlossener Picknickkorb und ein Glas Wasser auf einem Steg, die Sonne hoch über dem See', 'Un asciugamano, un cestino da picnic chiuso e un bicchiere d’acqua su un molo, il sole alto sul lago'], [BAIGNADE], {
    fr: { titre: 'Manger, boire de l’alcool, bronzer : ce qu’il faut éviter avant de se baigner', h1: 'Avant la baignade : repas, alcool et soleil', desc: 'Les maximes 2 et 3 de la Société Suisse de Sauvetage : pas d’alcool, ni estomac chargé ni à jeun, et pas de saut dans l’eau après un bain de soleil prolongé.',
      bref: 'La <strong>SSS</strong> déconseille de se baigner <strong>après de l’alcool ou des drogues, l’estomac chargé ou à jeun</strong> (maxime 2), et de <strong>sauter dans l’eau après un bain de soleil prolongé</strong> (maxime 3). Pour entrer dans l’eau : se doucher d’abord, ou entrer lentement en se mouillant les bras puis le visage et le haut du corps.',
      s: [['Alcool et drogues', P('Selon la SSS, l’alcool et les drogues altèrent l’état de conscience : on ne perçoit plus les situations dangereuses et on surestime ses capacités. L’alcool dilate en plus les vaisseaux sanguins : quand on nage, le sang se refroidit plus vite et afflue des bras et des jambes vers le centre du corps, ce qui augmente nettement le risque de syncope (hypothermie).')],
        ['Repas : ni trop plein ni à jeun', P('Après un repas, le corps dépense plus d’énergie pour digérer ; le cerveau étant moins bien irrigué, une activité sportive juste après peut donner vertiges et malaises, et, dans le pire des cas, la personne perd connaissance dans l’eau et se noie sans bruit. À l’inverse, la SSS déconseille de nager le ventre complètement vide : une hypoglycémie dans l’eau peut provoquer fringale et faiblesse.')],
        ['Après le soleil, le choc thermique', P('Sauter dans l’eau froide après un bain de soleil prolongé impose au corps un énorme choc thermique : douleurs musculaires, crampes et problèmes de circulation peuvent survenir ; dans le pire des cas, un choc froid, un évanouissement ou une crise cardiaque. La SSS conseille de prendre une douche avant, ou, à défaut, d’entrer lentement dans l’eau en y plongeant les bras l’un après l’autre et en s’aspergeant le visage et le haut du corps avant de plonger entièrement. À lire aussi : <a href="{blog:choc-thermique-eau-froide}">les 90 premières secondes dans l’eau froide</a>.')]] },
    en: { titre: 'Eating, drinking alcohol, sunbathing: what to avoid before swimming', h1: 'Before the swim: meals, alcohol and sun', desc: 'Rules 2 and 3 of the Swiss Lifesaving Society: no alcohol, neither a full nor an empty stomach, and no jumping in after prolonged sunbathing.',
      bref: 'The <strong>SLRG</strong> advises against swimming <strong>after alcohol or drugs, on a full or empty stomach</strong> (rule 2), and against <strong>jumping in after prolonged sunbathing</strong> (rule 3). To get in: shower first, or enter slowly wetting your arms, then face and upper body.',
      s: [['Alcohol and drugs', P('According to the SLRG, alcohol and drugs impair awareness: you no longer perceive dangerous situations and you overestimate your abilities. Alcohol also dilates blood vessels: when you swim, blood cools faster and flows from arms and legs to the core, which markedly raises the risk of fainting (hypothermia).')],
        ['Meals: neither too full nor fasting', P('After a meal the body spends more energy on digestion; with the brain less well supplied, exercise right afterwards can bring dizziness and faintness, and in the worst case the person loses consciousness in the water and drowns silently. Conversely, the SLRG advises against swimming on a completely empty stomach: low blood sugar in the water can bring hunger pangs and weakness.')],
        ['After the sun, the thermal shock', P('Jumping into cold water after prolonged sunbathing puts the body through a huge thermal shock: muscle pain, cramps and circulation problems can occur; in the worst case, cold shock, fainting or a heart attack. The SLRG advises showering first or, failing that, entering slowly, dipping your arms in one after the other and splashing your face and upper body before going fully under. Also read: <a href="{blog:choc-thermique-eau-froide}">the first 90 seconds in cold water</a>.')]] },
    de: { titre: 'Essen, Alkohol, Sonnenbad: was man vor dem Baden meiden sollte', h1: 'Vor dem Baden: Mahlzeit, Alkohol und Sonne', desc: 'Die Baderegeln 2 und 3 der Schweizerischen Lebensrettungs-Gesellschaft: kein Alkohol, weder voller noch leerer Magen, und nach langem Sonnenbad nicht ins Wasser springen.',
      bref: 'Die <strong>SLRG</strong> rät davon ab, <strong>nach Alkohol oder Drogen, mit vollem oder leerem Magen</strong> zu baden (Regel 2) und <strong>nach langem Sonnenbad ins Wasser zu springen</strong> (Regel 3). Zum Einstieg: zuerst duschen oder langsam hineingehen und Arme, dann Gesicht und Oberkörper nass machen.',
      s: [['Alkohol und Drogen', P('Laut SLRG trüben Alkohol und Drogen das Bewusstsein: Man erkennt gefährliche Situationen nicht mehr und überschätzt seine Fähigkeiten. Alkohol weitet zudem die Blutgefässe: Beim Schwimmen kühlt das Blut schneller ab und strömt aus Armen und Beinen zur Körpermitte, was das Risiko einer Ohnmacht (Unterkühlung) deutlich erhöht.')],
        ['Mahlzeit: weder zu voll noch nüchtern', P('Nach einer Mahlzeit braucht der Körper mehr Energie zum Verdauen; da das Gehirn schlechter durchblutet ist, können Sport und Bewegung direkt danach Schwindel und Unwohlsein auslösen, im schlimmsten Fall verliert die Person im Wasser das Bewusstsein und ertrinkt lautlos. Umgekehrt rät die SLRG, nicht mit ganz leerem Magen zu schwimmen: Unterzuckerung im Wasser kann Heisshunger und Schwäche auslösen.')],
        ['Nach der Sonne der Temperaturschock', P('Der Sprung ins kalte Wasser nach langem Sonnenbad bedeutet für den Körper einen enormen Temperaturschock: Muskelschmerzen, Krämpfe und Kreislaufprobleme können auftreten; im schlimmsten Fall ein Kälteschock, Ohnmacht oder Herzinfarkt. Die SLRG rät, vorher zu duschen oder sonst langsam hineinzugehen, die Arme nacheinander einzutauchen und Gesicht und Oberkörper zu bespritzen, bevor man ganz eintaucht. Lesenswert auch: <a href="{blog:choc-thermique-eau-froide}">die ersten 90 Sekunden im kalten Wasser</a>.')]] },
    it: { titre: 'Mangiare, bere alcol, prendere il sole: cosa evitare prima del bagno', h1: 'Prima del bagno: pasto, alcol e sole', desc: 'Le massime 2 e 3 della Società Svizzera di Salvataggio: niente alcol, né stomaco pieno né vuoto, e niente tuffi dopo un lungo bagno di sole.',
      bref: 'La <strong>SSS</strong> sconsiglia di fare il bagno <strong>dopo alcol o droghe, a stomaco pieno o vuoto</strong> (massima 2) e di <strong>tuffarsi dopo un lungo bagno di sole</strong> (massima 3). Per entrare: fare prima la doccia, o entrare lentamente bagnando le braccia, poi viso e busto.',
      s: [['Alcol e droghe', P('Secondo la SSS, alcol e droghe alterano lo stato di coscienza: non si percepiscono più le situazioni pericolose e si sopravvalutano le proprie capacità. L’alcol dilata inoltre i vasi sanguigni: nuotando, il sangue si raffredda più in fretta e affluisce da braccia e gambe al centro del corpo, il che aumenta nettamente il rischio di sincope (ipotermia).')],
        ['Pasto: né troppo pieno né digiuno', P('Dopo un pasto il corpo consuma più energia per digerire; essendo il cervello irrorato meno bene, un’attività sportiva subito dopo può dare vertigini e malori e, nel peggiore dei casi, la persona perde i sensi in acqua e annega in silenzio. Al contrario, la SSS sconsiglia di nuotare a stomaco completamente vuoto: un’ipoglicemia in acqua può provocare fame improvvisa e debolezza.')],
        ['Dopo il sole, lo shock termico', P('Tuffarsi in acqua fredda dopo un lungo bagno di sole impone al corpo un enorme shock termico: dolori muscolari, crampi e problemi di circolazione possono comparire; nel peggiore dei casi, shock da freddo, svenimento o infarto. La SSS consiglia di fare prima la doccia o, in mancanza, di entrare lentamente nell’acqua immergendo le braccia una dopo l’altra e bagnandosi viso e busto prima di immergersi del tutto. Da leggere anche: <a href="{blog:choc-thermique-eau-froide}">i primi 90 secondi in acqua fredda</a>.')]] } }),

  A('plonger-sauter-eau-inconnue', 'eau-inconnue', ['Un ponton qui s’avance sur une eau sombre et trouble, des branches affleurant près de la rive', 'A jetty reaching out over dark murky water, branches just breaking the surface near the shore', 'Ein Steg, der in dunkles trübes Wasser ragt, nahe dem Ufer knapp unter der Oberfläche liegende Äste', 'Un molo che si protende su acqua scura e torbida, rami che affiorano vicino alla riva'], [BAIGNADE, RIVIERES], {
    fr: { titre: 'Plonger ou sauter dans une eau inconnue : les dangers cachés, selon la SSS', h1: 'Ne pas plonger dans l’inconnu : ce que l’eau cache', desc: 'Maxime 4 de la Société Suisse de Sauvetage : pas de plongeon ni de saut dans une eau trouble ou inconnue. Blessures, courants, souches et rochers, et ce qui change après une tempête.',
      bref: 'La <strong>SSS</strong> demande de <strong>ne pas plonger ni sauter dans des eaux troubles ou inconnues</strong> : sauter dans une eau pas assez profonde peut causer de graves blessures au dos et à la tête, parfois fatales. Courants, tourbillons, souches, branches et rochers ne se voient pas depuis la berge, et peuvent se cacher même dans des lieux habituellement sûrs après de fortes tempêtes.',
      s: [['Pourquoi pas ?', P('Selon la SSS, sauter dans une eau pas assez profonde peut entraîner de graves blessures ; les blessures au dos et à la tête peuvent avoir une conséquence fatale. D’autres dangers ne sont pas visibles depuis la berge : courants, tourbillons, souches d’arbres, branches ou même rochers sous l’eau. Après de fortes tempêtes, ces dangers peuvent se cacher même dans des points d’eau habituellement sûrs.')],
        ['Et en cas de sauvetage ?', P('Même dans le cadre d’un sauvetage, s’il faut sauter dans une eau inconnue, la SSS demande de sauter les pieds en avant et d’éviter ainsi de plonger profondément.')],
        ['Connaître d’abord le lieu', P('Pour les cours d’eau, la SSS conseille de reconnaître le trajet avant de s’y engager : seuils et rochers créent tourbillons et courants, et la profondeur et les courants varient, notamment après une longue sécheresse ou de fortes pluies. Elle recommande aussi de demander conseil aux personnes habituées aux lieux (services de sauvetage, police, pêcheurs, canoéistes). Pour le Léman : <a href="{blog:plages-geneve}">les plages de Genève</a>, <a href="{app}">l’app</a> donne l’eau et le vent du moment.')]] },
    en: { titre: 'Diving or jumping into unknown water: hidden dangers, according to the SLRG', h1: 'Do not dive into the unknown: what the water hides', desc: 'Rule 4 of the Swiss Lifesaving Society: no diving or jumping into murky or unknown water. Injuries, currents, stumps and rocks, and what changes after a storm.',
      bref: 'The <strong>SLRG</strong> asks you <strong>not to dive or jump into murky or unknown water</strong>: jumping into water that is too shallow can cause serious back and head injuries, sometimes fatal. Currents, eddies, stumps, branches and rocks cannot be seen from the bank, and can hide even in usually safe spots after heavy storms.',
      s: [['Why not?', P('According to the SLRG, jumping into water that is not deep enough can cause serious injuries; back and head injuries can be fatal. Other dangers cannot be seen from the bank: currents, eddies, tree stumps, branches or even rocks under the water. After heavy storms, these dangers can hide even in normally safe spots.')],
        ['And in a rescue?', P('Even in a rescue, if you must jump into unknown water, the SLRG asks you to jump feet first and so avoid going deep.')],
        ['Know the place first', P('For watercourses, the SLRG advises scouting the route before setting off: weirs and rocks create eddies and currents, and depth and currents vary, especially after a long drought or heavy rain. It also recommends asking people who know the place (rescue services, police, anglers, canoeists). For Lake Geneva: <a href="{blog:plages-geneve}">the beaches of Geneva</a>; <a href="{app}">the app</a> gives the current water and wind.')]] },
    de: { titre: 'In unbekanntes Wasser springen oder tauchen: versteckte Gefahren, laut SLRG', h1: 'Nicht ins Unbekannte springen: was das Wasser verbirgt', desc: 'Baderegel 4 der Schweizerischen Lebensrettungs-Gesellschaft: nicht in trübes oder unbekanntes Wasser springen oder tauchen. Verletzungen, Strömungen, Baumstümpfe und Felsen und was sich nach einem Sturm ändert.',
      bref: 'Die <strong>SLRG</strong> bittet, <strong>nicht in trübes oder unbekanntes Wasser zu springen oder zu tauchen</strong>: Ein Sprung in zu seichtes Wasser kann schwere, mitunter tödliche Rücken- und Kopfverletzungen verursachen. Strömungen, Strudel, Baumstümpfe, Äste und Felsen sind vom Ufer aus nicht sichtbar und können sich nach starken Stürmen selbst an üblicherweise sicheren Stellen verbergen.',
      s: [['Warum nicht?', P('Laut SLRG kann ein Sprung in nicht tiefes Wasser zu schweren Verletzungen führen; Rücken- und Kopfverletzungen können tödlich sein. Andere Gefahren sind vom Ufer aus nicht sichtbar: Strömungen, Strudel, Baumstümpfe, Äste oder sogar Felsen unter Wasser. Nach starken Stürmen können sich diese Gefahren selbst an normalerweise sicheren Stellen verbergen.')],
        ['Und bei einer Rettung?', P('Auch bei einer Rettung bittet die SLRG, wenn man in unbekanntes Wasser springen muss, mit den Füssen voran zu springen und so nicht tief einzutauchen.')],
        ['Den Ort zuerst kennen', P('Bei Fliessgewässern rät die SLRG, die Strecke vor dem Einstieg zu erkunden: Schwellen und Felsen erzeugen Strudel und Strömungen, und Tiefe und Strömung wechseln, besonders nach langer Trockenheit oder starkem Regen. Sie empfiehlt auch, Ortskundige zu fragen (Rettungsdienste, Polizei, Fischer, Kanufahrer). Für den Genfersee: <a href="{blog:plages-geneve}">die Strände von Genf</a>; <a href="{app}">die App</a> zeigt Wasser und Wind von heute.')]] },
    it: { titre: 'Tuffarsi o saltare in acqua sconosciuta: pericoli nascosti, secondo la SSS', h1: 'Non tuffarsi nell’ignoto: cosa nasconde l’acqua', desc: 'Massima 4 della Società Svizzera di Salvataggio: niente tuffi in acque torbide o sconosciute. Ferite, correnti, ceppi e rocce, e cosa cambia dopo una tempesta.',
      bref: 'La <strong>SSS</strong> chiede di <strong>non tuffarsi né saltare in acque torbide o sconosciute</strong>: saltare in acqua non abbastanza profonda può causare gravi ferite alla schiena e alla testa, a volte fatali. Correnti, vortici, ceppi, rami e rocce non si vedono dalla riva e possono nascondersi, dopo forti tempeste, anche in luoghi di solito sicuri.',
      s: [['Perché no?', P('Secondo la SSS, saltare in acqua non abbastanza profonda può causare gravi ferite; le ferite a schiena e testa possono avere conseguenze fatali. Altri pericoli non sono visibili dalla riva: correnti, vortici, ceppi d’albero, rami o perfino rocce sott’acqua. Dopo forti tempeste questi pericoli possono nascondersi anche in punti d’acqua di solito sicuri.')],
        ['E in un salvataggio?', P('Anche in un salvataggio, se bisogna saltare in acqua sconosciuta, la SSS chiede di saltare con i piedi in avanti, evitando così di immergersi in profondità.')],
        ['Conoscere prima il luogo', P('Per i corsi d’acqua, la SSS consiglia di riconoscere il percorso prima di partire: soglie e rocce creano vortici e correnti, e profondità e correnti variano, soprattutto dopo una lunga siccità o forti piogge. Raccomanda anche di chiedere a chi conosce i luoghi (servizi di salvataggio, polizia, pescatori, canoisti). Per il Lemano: <a href="{blog:plages-geneve}">le spiagge di Ginevra</a>; <a href="{app}">l’app</a> dà acqua e vento del momento.')]] } }),

  A('matelas-pneumatiques-bouees-eau-profonde', 'bouees', ['Un matelas pneumatique coloré qui dérive seul au large, le rivage petit au loin', 'A colourful air mattress drifting alone offshore, the shore small in the distance', 'Eine bunte Luftmatratze, die allein vor dem Ufer treibt, das Ufer klein in der Ferne', 'Un materassino colorato che alla deriva da solo al largo, la riva piccola in lontananza'], [BAIGNADE, RIVIERES], {
    fr: { titre: 'Matelas pneumatiques et bouées en eau profonde : pourquoi la SSS les déconseille', h1: 'Matelas et bouées : une fausse sécurité en eau profonde', desc: 'Maxime 5 de la Société Suisse de Sauvetage : pas de matelas pneumatique ni de matériel auxiliaire de natation en eau profonde. Dérive, trous, et l’alternative : le gilet de sauvetage.',
      bref: 'La <strong>SSS</strong> demande de <strong>ne pas utiliser matelas pneumatiques ni matériel auxiliaire de natation en eau profonde</strong> : ils sont difficiles à manœuvrer, un mauvais nageur peut dériver loin de la rive, et un matelas peut perdre son air. La meilleure alternative, selon elle : un <strong>gilet de sauvetage</strong> à corps flottant solide. Sur l’eau, le gilet est recommandé pour toutes les embarcations, même au plus chaud de l’été.',
      s: [['Le problème', P('Selon la SSS, une aide à la flottaison ou un matelas pneumatique est difficile, voire impossible à manœuvrer : un mauvais nageur risque de dériver loin de la rive malgré l’aide, et de ne plus pouvoir sortir de l’eau par ses propres moyens. Les matelas peuvent perdre leur flottabilité à cause de trous causés par exemple par des pierres à arêtes vives ou par le soleil. En cas de problème de santé, notamment de perte de conscience, ils n’apportent dans la plupart des cas aucune aide.')],
        ['L’alternative', P('La SSS indique qu’un gilet de sauvetage doté d’un corps flottant solide est la meilleure alternative. Pour les promenades en canot, en barque, en pédalo, en canoë ou en radeau, elle recommande de toujours porter un gilet de sauvetage adapté, même au plus chaud de l’été : même un nageur entraîné peut recevoir un choc à la tête en cas de chute, perdre connaissance ou être surpris par la température de l’eau.')],
        ['Pour les enfants', P('Même règle : brassards et animaux gonflables ne remplacent pas la surveillance : voir <a href="{blog:enfants-au-bord-de-l-eau}">enfants au bord de l’eau</a>. Pour louer sur l’eau, voir l’onglet « Louer » de l’<a href="{app}">app</a>.')]] },
    en: { titre: 'Air mattresses and floats in deep water: why the SLRG advises against them', h1: 'Mattresses and floats: false security in deep water', desc: 'Rule 5 of the Swiss Lifesaving Society: no air mattresses or swimming aids in deep water. Drifting, punctures, and the alternative: a life jacket.',
      bref: 'The <strong>SLRG</strong> asks you <strong>not to use air mattresses or swimming aids in deep water</strong>: they are hard to steer, a weak swimmer can drift far from shore, and a mattress can lose its air. Its best alternative: a <strong>life jacket</strong> with a solid buoyancy body. On the water, a life jacket is recommended for every craft, even in the heat of summer.',
      s: [['The problem', P('According to the SLRG, a flotation aid or air mattress is hard, even impossible, to steer: a weak swimmer risks drifting far from shore despite the aid, and no longer being able to get out of the water unaided. Mattresses can lose buoyancy through punctures caused, for example, by sharp-edged stones or by the sun. In a health emergency, in particular loss of consciousness, they are of no help in most cases.')],
        ['The alternative', P('The SLRG says a life jacket with a solid buoyancy body is the best alternative. For trips by dinghy, rowing boat, pedalo, canoe or raft, it recommends always wearing a suitable life jacket, even in the heat of summer: even a trained swimmer can hit their head in a fall, lose consciousness or be caught out by the water temperature.')],
        ['For children', P('Same rule: armbands and inflatable animals do not replace supervision: see <a href="{blog:enfants-au-bord-de-l-eau}">children at the water’s edge</a>. To rent on the water, see the “Rent” tab of the <a href="{app}">app</a>.')]] },
    de: { titre: 'Luftmatratzen und Schwimmhilfen im tiefen Wasser: warum die SLRG abrät', h1: 'Matratzen und Schwimmhilfen: trügerische Sicherheit im tiefen Wasser', desc: 'Baderegel 5 der Schweizerischen Lebensrettungs-Gesellschaft: keine Luftmatratzen und Schwimmhilfen im tiefen Wasser. Abtreiben, Löcher und die Alternative: die Rettungsweste.',
      bref: 'Die <strong>SLRG</strong> bittet, <strong>Luftmatratzen und Schwimmhilfen nicht im tiefen Wasser zu verwenden</strong>: Sie sind schwer zu steuern, ein schlechter Schwimmer kann weit vom Ufer abtreiben, und eine Matratze kann Luft verlieren. Die beste Alternative laut SLRG: eine <strong>Rettungsweste</strong> mit festem Auftriebskörper. Auf dem Wasser wird die Weste für alle Boote empfohlen, auch im heissesten Sommer.',
      s: [['Das Problem', P('Laut SLRG ist eine Schwimmhilfe oder Luftmatratze schwer, ja kaum zu steuern: Ein schlechter Schwimmer riskiert, trotz der Hilfe weit vom Ufer abzutreiben und nicht mehr aus eigener Kraft aus dem Wasser zu kommen. Matratzen können durch Löcher, etwa von scharfkantigen Steinen oder von der Sonne, ihren Auftrieb verlieren. Bei gesundheitlichen Problemen, besonders Bewusstlosigkeit, helfen sie in den meisten Fällen nicht.')],
        ['Die Alternative', P('Die SLRG nennt eine Rettungsweste mit festem Auftriebskörper als beste Alternative. Bei Fahrten mit Schlauchboot, Ruderboot, Pedalo, Kanu oder Floss empfiehlt sie, immer eine passende Rettungsweste zu tragen, auch im heissesten Sommer: Selbst ein geübter Schwimmer kann sich bei einem Sturz den Kopf anschlagen, das Bewusstsein verlieren oder von der Wassertemperatur überrascht werden.')],
        ['Für Kinder', P('Dieselbe Regel: Schwimmflügel und aufblasbare Tiere ersetzen die Aufsicht nicht: siehe <a href="{blog:enfants-au-bord-de-l-eau}">Kinder am Wasser</a>. Zum Mieten auf dem Wasser siehe den Reiter «Mieten» der <a href="{app}">App</a>.')]] },
    it: { titre: 'Materassini e galleggianti in acqua profonda: perché la SSS li sconsiglia', h1: 'Materassini e galleggianti: falsa sicurezza in acqua profonda', desc: 'Massima 5 della Società Svizzera di Salvataggio: niente materassini né ausili al nuoto in acqua profonda. Deriva, buchi e l’alternativa: il giubbotto di salvataggio.',
      bref: 'La <strong>SSS</strong> chiede di <strong>non usare materassini né ausili al nuoto in acqua profonda</strong>: sono difficili da manovrare, un cattivo nuotatore può andare alla deriva lontano dalla riva e un materassino può perdere aria. La migliore alternativa secondo la SSS: un <strong>giubbotto di salvataggio</strong> con corpo galleggiante solido. Sull’acqua il giubbotto è raccomandato per ogni imbarcazione, anche nel caldo estivo.',
      s: [['Il problema', P('Secondo la SSS, un ausilio al galleggiamento o un materassino è difficile, anzi impossibile da manovrare: un cattivo nuotatore rischia di andare alla deriva lontano dalla riva nonostante l’ausilio e di non riuscire più a uscire dall’acqua da solo. I materassini possono perdere galleggiabilità per buchi causati, per esempio, da pietre spigolose o dal sole. In caso di problemi di salute, in particolare perdita di coscienza, nella maggior parte dei casi non servono.')],
        ['L’alternativa', P('La SSS indica che un giubbotto di salvataggio con corpo galleggiante solido è la migliore alternativa. Per le gite in canotto, barca a remi, pedalò, canoa o zattera, raccomanda di indossare sempre un giubbotto adatto, anche nel caldo estivo: perfino un nuotatore allenato può battere la testa in una caduta, perdere i sensi o essere sorpreso dalla temperatura dell’acqua.')],
        ['Per i bambini', P('Stessa regola: braccioli e animali gonfiabili non sostituiscono la sorveglianza: vedi <a href="{blog:enfants-au-bord-de-l-eau}">bambini in riva all’acqua</a>. Per noleggiare sull’acqua, vedi la scheda «Noleggio» dell’<a href="{app}">app</a>.')]] } }),

  A('nager-seul-eau-libre', 'nager-seul', ['Une silhouette de bouée orange flottant au large d’une rive lointaine, un nageur absent, le lac calme', 'An orange tow-float silhouette bobbing offshore of a distant shore, no swimmer visible, the lake calm', 'Die Silhouette einer orangen Schwimmboje weit vor einem fernen Ufer, kein Schwimmer sichtbar, der See ruhig', 'La sagoma di una boa arancione che galleggia al largo di una riva lontana, nessun nuotatore, il lago calmo'], [BAIGNADE, RIVIERES], {
    fr: { titre: 'Nager seul en eau libre : ce que dit la Société Suisse de Sauvetage', h1: 'Nager seul sur de longues distances : pourquoi pas', desc: 'Maxime 6 de la SSS : ne jamais nager seul sur de longues distances. Crampes, malaises, la bouée Baywatch, et pourquoi seuls les bons nageurs vont en eau libre.',
      bref: 'La <strong>SSS</strong> demande de <strong>ne jamais nager seul sur de longues distances</strong> : même le corps le mieux entraîné peut avoir une défaillance. En cas de crampe ou de malaise, une seconde personne peut aider ou appeler du renfort. Pour s’entraîner seul, elle recommande une <strong>bouée Baywatch ou une ceinture de sauvetage</strong> à laquelle s’agripper. Et elle précise que seuls les bons nageurs s’aventurent en eau libre.',
      s: [['Pourquoi pas seul ?', P('Selon la SSS, même le corps le mieux entraîné peut avoir une défaillance. En cas de crampe ou de malaise, une seconde personne peut aider à calmer la crampe ou appeler du renfort.')],
        ['Si on s’entraîne seul', P('La SSS recommande d’emporter une bouée Baywatch ou une ceinture de sauvetage : en cas de fatigue ou de crampe, on peut s’agripper à l’objet flottant et récupérer.')],
        ['Eau libre : réservée aux bons nageurs', P('La SSS écrit que seuls les bons nageurs s’aventurent dans des eaux libres (rivières, étangs et lacs), qui dissimulent courants, affouillements ou lames de fond. Elle conseille aux nageurs inexpérimentés de ne pas y rester sans surveillance formée, et de prendre conseil auprès des personnes habituées aux lieux. Voir aussi <a href="{blog:bain-d-hiver-en-groupe-suisse}">le bain d’hiver en groupe</a>.')]] },
    en: { titre: 'Swimming alone in open water: what the Swiss Lifesaving Society says', h1: 'Swimming long distances alone: why not', desc: 'SLRG rule 6: never swim long distances alone. Cramps, faintness, the Baywatch buoy, and why only good swimmers go into open water.',
      bref: 'The <strong>SLRG</strong> asks you to <strong>never swim long distances alone</strong>: even the best-trained body can fail. In a cramp or a faint spell, a second person can help or call for backup. To train alone, it recommends a <strong>Baywatch buoy or rescue belt</strong> to hold on to. And it says only good swimmers venture into open water.',
      s: [['Why not alone?', P('According to the SLRG, even the best-trained body can fail. In a cramp or a faint spell, a second person can help ease the cramp or call for backup.')],
        ['If you train alone', P('The SLRG recommends carrying a Baywatch buoy or rescue belt: if you tire or cramp, you can hold on to the floating object and recover.')],
        ['Open water: for good swimmers only', P('The SLRG writes that only good swimmers venture into open water (rivers, ponds and lakes), which hide currents, scour holes or undertow. It advises inexperienced swimmers not to stay there without trained supervision, and to take advice from people who know the place. See also <a href="{blog:bain-d-hiver-en-groupe-suisse}">winter swimming in a group</a>.')]] },
    de: { titre: 'Allein im Freiwasser schwimmen: was die Schweizerische Lebensrettungs-Gesellschaft sagt', h1: 'Allein lange Strecken schwimmen: warum nicht', desc: 'SLRG-Baderegel 6: nie allein lange Strecken schwimmen. Krämpfe, Unwohlsein, die Baywatch-Boje und warum nur gute Schwimmer ins Freiwasser gehen.',
      bref: 'Die <strong>SLRG</strong> bittet, <strong>nie allein lange Strecken zu schwimmen</strong>: Selbst der bestgeübte Körper kann versagen. Bei Krampf oder Unwohlsein kann eine zweite Person helfen oder Verstärkung rufen. Wer allein trainiert, nimmt laut SLRG eine <strong>Baywatch-Boje oder einen Rettungsgurt</strong> zum Festhalten mit. Und nur gute Schwimmer wagen sich ins Freiwasser.',
      s: [['Warum nicht allein?', P('Laut SLRG kann selbst der bestgeübte Körper versagen. Bei Krampf oder Unwohlsein kann eine zweite Person helfen, den Krampf zu lösen, oder Verstärkung rufen.')],
        ['Wenn man allein trainiert', P('Die SLRG empfiehlt, eine Baywatch-Boje oder einen Rettungsgurt mitzunehmen: Bei Müdigkeit oder Krampf kann man sich am Schwimmkörper festhalten und erholen.')],
        ['Freiwasser: nur für gute Schwimmer', P('Die SLRG schreibt, nur gute Schwimmer wagten sich in Freigewässer (Flüsse, Teiche und Seen), die Strömungen, Auskolkungen oder Sogwirkung verbergen. Unerfahrenen rät sie, sich dort nicht ohne geschulte Aufsicht aufzuhalten und Ortskundige zu fragen. Siehe auch <a href="{blog:bain-d-hiver-en-groupe-suisse}">Winterbaden in der Gruppe</a>.')]] },
    it: { titre: 'Nuotare da soli in acque libere: cosa dice la Società Svizzera di Salvataggio', h1: 'Nuotare da soli su lunghe distanze: perché no', desc: 'Massima 6 della SSS: mai nuotare da soli su lunghe distanze. Crampi, malori, la boa Baywatch e perché solo i buoni nuotatori vanno in acque libere.',
      bref: 'La <strong>SSS</strong> chiede di <strong>non nuotare mai da soli su lunghe distanze</strong>: anche il corpo meglio allenato può cedere. In caso di crampo o malore, una seconda persona può aiutare o chiamare rinforzi. Per allenarsi da soli raccomanda una <strong>boa Baywatch o una cintura di salvataggio</strong> a cui aggrapparsi. E solo i buoni nuotatori si avventurano in acque libere.',
      s: [['Perché non da soli?', P('Secondo la SSS, anche il corpo meglio allenato può cedere. In caso di crampo o malore, una seconda persona può aiutare a calmare il crampo o chiamare rinforzi.')],
        ['Se ci si allena da soli', P('La SSS raccomanda di portare una boa Baywatch o una cintura di salvataggio: in caso di stanchezza o crampo ci si può aggrappare all’oggetto galleggiante e riprendersi.')],
        ['Acque libere: per buoni nuotatori', P('La SSS scrive che solo i buoni nuotatori si avventurano in acque libere (fiumi, stagni e laghi), che nascondono correnti, gorghi o risacche. Consiglia ai nuotatori inesperti di non restarvi senza sorveglianza formata e di chiedere consiglio a chi conosce i luoghi. Vedi anche <a href="{blog:bain-d-hiver-en-groupe-suisse}">il bagno invernale in gruppo</a>.')]] } }),

  A('crampes-hypothermie-sejour-prolonge-eau-froide', 'crampes', ['Un thermomètre d’eau accroché à un poteau, une main hors cadre qui s’éloigne, brume sur le lac froid', 'A water thermometer hung on a post, a hand out of frame moving away, mist on the cold lake', 'Ein Wasserthermometer an einem Pfosten, eine Hand ausserhalb des Bildes entfernt sich, Dunst über dem kalten See', 'Un termometro per l’acqua appeso a un palo, una mano fuori campo che si allontana, foschia sul lago freddo'], [RIVIERES, HELSANA], {
    fr: { titre: 'Crampes et hypothermie : pourquoi un séjour prolongé en eau froide est risqué', h1: 'Crampes, froid et noyade : ce que dit la SSS du séjour prolongé', desc: 'Un séjour prolongé dans l’eau peut causer des crampes ; plus l’eau est froide, plus il faut rester peu de temps. L’hypothermie, les eaux libres suisses sous 14 °C et ce que la SSS ne chiffre pas.',
      bref: 'Selon la <strong>SSS</strong>, un séjour prolongé dans l’eau peut causer des <strong>crampes musculaires</strong>, et <strong>plus l’eau est froide, plus le séjour doit être court</strong>. Le corps ne régule sa température que jusqu’à environ 35 °C de température centrale ; en dessous, c’est l’<strong>hypothermie</strong> : crampes, troubles de la circulation, risque de noyade nettement plus élevé. La SSS ne donne pas de durée maximale officielle, la réaction au froid variant beaucoup d’une personne à l’autre.',
      s: [['Ce que dit la SSS', P('La SSS écrit que la tolérance de notre corps au froid est très faible : le mécanisme de régulation ne fonctionne que jusqu’à une baisse de la température centrale à environ 35 °C. Au-delà, on parle d’hypothermie : le corps perd de ses capacités, des crampes musculaires et des troubles de la circulation sanguine apparaissent, ce qui augmente considérablement le risque de noyade.')],
        ['Les eaux libres suisses', P('Selon la SSS, les eaux libres suisses ont en moyenne une température inférieure à 14 °C pendant 7 mois de l’année, et pendant 5 de ces 7 mois, l’eau est à moins de 8 °C.')],
        ['Quelle durée ?', P('La SSS précise que, la réaction du corps à l’eau froide variant énormément d’une personne à l’autre, elle n’est pas en mesure de fournir d’indications officielles sur la durée maximale possible de séjour dans l’eau froide. La règle d’une minute par degré que reprennent d’autres sources (Helsana) est un repère de prudence, pas une limite garantie : voir <a href="{blog:programme-4-semaines-bain-d-hiver}">notre programme de 4 semaines</a>.')],
        ['Pour aller plus loin', P('La SSS propose un module « Hypothermie » pour les nageurs sauveteurs. Côté pratique : <a href="{blog:afterdrop-se-rechauffer}">se réchauffer après le bain</a>, <a href="{blog:choc-thermique-eau-froide}">les 90 premières secondes</a>.')]] },
    en: { titre: 'Cramps and hypothermia: why a long stay in cold water is risky', h1: 'Cramps, cold and drowning: what the SLRG says about a long stay', desc: 'A prolonged stay in the water can cause cramps; the colder the water, the shorter the stay should be. Hypothermia, Swiss open waters below 14 °C and what the SLRG does not put a number on.',
      bref: 'According to the <strong>SLRG</strong>, a prolonged stay in the water can cause <strong>muscle cramps</strong>, and <strong>the colder the water, the shorter the stay should be</strong>. The body regulates its temperature only down to about 35 °C core temperature; below that is <strong>hypothermia</strong>: cramps, circulation problems, a markedly higher drowning risk. The SLRG gives no official maximum time, as reaction to cold varies greatly from person to person.',
      s: [['What the SLRG says', P('The SLRG writes that our body’s tolerance to cold is very low: the regulation mechanism works only until core temperature falls to about 35 °C. Beyond that, it is called hypothermia: the body loses capacity, muscle cramps and circulation problems appear, which considerably raises the drowning risk.')],
        ['Swiss open waters', P('According to the SLRG, Swiss open waters average below 14 °C for 7 months of the year, and for 5 of those 7 months the water is below 8 °C.')],
        ['How long?', P('The SLRG states that, since the body’s reaction to cold water varies enormously from person to person, it cannot give official guidance on the maximum possible stay in cold water. The minutes-equal-degrees rule that other sources repeat (Helsana) is a rule of caution, not a guaranteed limit: see <a href="{blog:programme-4-semaines-bain-d-hiver}">our 4-week programme</a>.')],
        ['To go further', P('The SLRG offers a “Hypothermia” module for lifeguard swimmers. In practice: <a href="{blog:afterdrop-se-rechauffer}">warming up after the swim</a>, <a href="{blog:choc-thermique-eau-froide}">the first 90 seconds</a>.')]] },
    de: { titre: 'Krämpfe und Unterkühlung: warum ein langer Aufenthalt in kaltem Wasser riskant ist', h1: 'Krämpfe, Kälte und Ertrinken: was die SLRG zum langen Aufenthalt sagt', desc: 'Ein langer Aufenthalt im Wasser kann Krämpfe auslösen; je kälter das Wasser, desto kürzer sollte er sein. Unterkühlung, Schweizer Freigewässer unter 14 °C und was die SLRG nicht beziffert.',
      bref: 'Laut <strong>SLRG</strong> kann ein langer Aufenthalt im Wasser <strong>Muskelkrämpfe</strong> auslösen, und <strong>je kälter das Wasser, desto kürzer sollte der Aufenthalt sein</strong>. Der Körper reguliert seine Temperatur nur bis etwa 35 °C Kerntemperatur; darunter spricht man von <strong>Unterkühlung</strong>: Krämpfe, Kreislaufstörungen, deutlich höheres Ertrinkungsrisiko. Die SLRG gibt keine offizielle Höchstdauer an, da die Reaktion auf Kälte von Person zu Person stark variiert.',
      s: [['Was die SLRG sagt', P('Die SLRG schreibt, die Kältetoleranz unseres Körpers sei sehr gering: Der Regulationsmechanismus funktioniere nur, bis die Kerntemperatur auf etwa 35 °C sinkt. Darunter spricht man von Unterkühlung: Der Körper verliert Fähigkeiten, Muskelkrämpfe und Kreislaufstörungen treten auf, was das Ertrinkungsrisiko erheblich erhöht.')],
        ['Schweizer Freigewässer', P('Laut SLRG haben Schweizer Freigewässer im Mittel 7 Monate im Jahr weniger als 14 °C, und in 5 dieser 7 Monate liegt das Wasser unter 8 °C.')],
        ['Wie lange?', P('Die SLRG hält fest, da die Reaktion des Körpers auf kaltes Wasser von Person zu Person enorm variiere, könne sie keine offiziellen Angaben zur maximal möglichen Aufenthaltsdauer im kalten Wasser machen. Die Regel «so viele Minuten wie Grad», die andere Quellen nennen (Helsana), ist eine Vorsichtsregel, keine garantierte Grenze: siehe <a href="{blog:programme-4-semaines-bain-d-hiver}">unser 4-Wochen-Programm</a>.')],
        ['Zum Weiterlesen', P('Die SLRG bietet ein Modul «Unterkühlung» für Rettungsschwimmer an. Praktisch: <a href="{blog:afterdrop-se-rechauffer}">sich nach dem Bad aufwärmen</a>, <a href="{blog:choc-thermique-eau-froide}">die ersten 90 Sekunden</a>.')]] },
    it: { titre: 'Crampi e ipotermia: perché una permanenza prolungata in acqua fredda è rischiosa', h1: 'Crampi, freddo e annegamento: cosa dice la SSS della permanenza prolungata', desc: 'Una permanenza prolungata in acqua può causare crampi; più l’acqua è fredda, più deve essere breve. L’ipotermia, le acque libere svizzere sotto i 14 °C e ciò che la SSS non quantifica.',
      bref: 'Secondo la <strong>SSS</strong>, una permanenza prolungata in acqua può causare <strong>crampi muscolari</strong>, e <strong>più l’acqua è fredda, più la permanenza deve essere breve</strong>. Il corpo regola la temperatura solo fino a circa 35 °C di temperatura centrale; sotto si parla di <strong>ipotermia</strong>: crampi, disturbi della circolazione, rischio di annegamento nettamente più alto. La SSS non dà una durata massima ufficiale, perché la reazione al freddo varia molto da persona a persona.',
      s: [['Cosa dice la SSS', P('La SSS scrive che la tolleranza del nostro corpo al freddo è molto bassa: il meccanismo di regolazione funziona solo finché la temperatura centrale scende a circa 35 °C. Oltre, si parla di ipotermia: il corpo perde capacità, compaiono crampi muscolari e disturbi della circolazione, il che aumenta considerevolmente il rischio di annegamento.')],
        ['Le acque libere svizzere', P('Secondo la SSS, le acque libere svizzere hanno in media una temperatura inferiore a 14 °C per 7 mesi all’anno, e per 5 di questi 7 mesi l’acqua è sotto gli 8 °C.')],
        ['Per quanto tempo?', P('La SSS precisa che, poiché la reazione del corpo all’acqua fredda varia enormemente da persona a persona, non è in grado di fornire indicazioni ufficiali sulla durata massima possibile di permanenza in acqua fredda. La regola «tanti minuti quanti gradi» ripresa da altre fonti (Helsana) è un criterio di prudenza, non un limite garantito: vedi <a href="{blog:programme-4-semaines-bain-d-hiver}">il nostro programma di 4 settimane</a>.')],
        ['Per approfondire', P('La SSS propone un modulo «Ipotermia» per i nuotatori soccorritori. In pratica: <a href="{blog:afterdrop-se-rechauffer}">riscaldarsi dopo il bagno</a>, <a href="{blog:choc-thermique-eau-froide}">i primi 90 secondi</a>.')]] } }),
];
